CREATE TABLE IF NOT EXISTS events ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', contact_name TEXT NOT NULL DEFAULT '', contact_email TEXT NOT NULL DEFAULT '', published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE TABLE IF NOT EXISTS slots ( id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, title TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', date TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 1, start_utc TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS idx_slots_event ON slots(event_id); CREATE INDEX IF NOT EXISTS idx_slots_start ON slots(start_utc); CREATE TABLE IF NOT EXISTS signups ( id INTEGER PRIMARY KEY AUTOINCREMENT, slot_id INTEGER NOT NULL REFERENCES slots(id) ON DELETE CASCADE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL, mobile TEXT NOT NULL, comments TEXT NOT NULL DEFAULT '', manage_token TEXT NOT NULL, reminder_sent INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_signups_slot ON signups(slot_id); CREATE INDEX IF NOT EXISTS idx_signups_token ON signups(manage_token); CREATE UNIQUE INDEX IF NOT EXISTS idx_signups_unique ON signups(slot_id, email); CREATE TABLE IF NOT EXISTS email_queue ( id INTEGER PRIMARY KEY AUTOINCREMENT, to_email TEXT NOT NULL, reply_to TEXT, subject TEXT NOT NULL, html TEXT NOT NULL, ics TEXT, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), sent_at TEXT ); CREATE INDEX IF NOT EXISTS idx_email_status ON email_queue(status, sent_at); CREATE TABLE IF NOT EXISTS login_attempts ( ip TEXT NOT NULL, at TEXT NOT NULL DEFAULT (datetime('now')) );